/* DWARF original prototype: int GetSkillMasterType(CHARACTER * this, DWORD dwVnum) */

int __thiscall CHARACTER::GetSkillMasterType(CHARACTER *this,DWORD dwVnum)

{
  char *pcVar1;
  
  if ((this->super_CEntity).m_lpDesc != (LPDESC)0x0) {
    if (dwVnum < 0xff) {
      if (this->m_pSkillLevels == (TPlayerSkill *)0x0) {
        return 0;
      }
      return (uint)this->m_pSkillLevels[dwVnum].bMasterType;
    }
    pcVar1 = GetName(this);
    _sys_err("GetSkillMasterType",0xa07,"%s skill vnum overflow %lu",pcVar1,dwVnum);
  }
  return 0;
}
